mkdir -p /tmp/rn && cat > /tmp/rn/fix.mjs <<'EOF'
import fs from 'fs';
const lines = fs.readFileSync('/tmp/uses.txt','utf8').trim().split('\n');
let n=0, miss=[];
const byFile = {};
for (const l of lines) { const m = l.trim().match(/^(\S+):(\d+)\s+<([\w-]+)>/); (byFile[m[1].replace(/\\/g,'/')] ??= []).push([+m[2], m[3]]); }
for (const [f, items] of Object.entries(byFile)) {
  const src = fs.readFileSync(f,'utf8').split('\n');
  for (const [ln, tag] of items) {
    const re = new RegExp(`<${tag}\\b[^>]*>`, 'g');
    const before = src[ln-1];
    src[ln-1] = before.replace(re, t => t.replace(/(\[?)disableTooltip\b/, (_,b)=>{n++; return b+'hideHint';}));
    if (src[ln-1] === before) miss.push(`${f}:${ln} ${before}`);
  }
  fs.writeFileSync(f, src.join('\n'));
}
console.log('edits', n); console.log(miss.join('\n'));
EOF
node /tmp/rn/fix.mjs

