import fs from 'fs';
import { execSync } from 'child_process';
let total = 0;
for (let iter = 0; iter < 10; iter++) {
  let out = '';
  try { out = execSync('npx ngc -p tsconfig.json', { encoding: 'utf8', stdio: 'pipe' }); }
  catch (e) { out = (e.stdout || '') + (e.stderr || ''); }
  out = out.replace(/\x1b\[[0-9;]*m/g, '');
  const errs = [...out.matchAll(/^(\S+?):(\d+):(\d+) - error TS(\d+): (.*)$/gm)];
  console.log('iter', iter, 'errors', errs.length);
  if (!errs.length) break;
  let fixed = 0;
  const byFile = {};
  for (const [, f, l, c, code, msg] of errs) {
    if (code === '2339' && /'disableTooltip' does not exist on type '(PillComponent|FancyPillComponent|StatusPillComponent)'/.test(msg)) {
      (byFile[f] ??= []).push([+l, +c]);
    } else console.log('OTHER', f, l, c, code, msg);
  }
  for (const [f, pos] of Object.entries(byFile)) {
    const src = fs.readFileSync(f, 'utf8').split('\n');
    for (const [l, c] of pos) {
      const line = src[l - 1];
      if (line.substr(c - 1, 14) === 'disableTooltip') {
        src[l - 1] = line.slice(0, c - 1) + 'hideHint' + line.slice(c - 1 + 14);
        fixed++; console.log('fix', f + ':' + l);
      } else console.log('NOMATCH', f, l, c, line);
    }
    fs.writeFileSync(f, src.join('\n'));
  }
  total += fixed;
  if (!fixed) break;
}
console.log('total', total);

